CREATE PROCEDURE [dbo].[sp_AMAR_MASRAF] @FROMDATE BIGINT, @TODATE BIGINT, @KONTROL INT AS BEGIN WITH MASRAF_SUB_CTE AS ( SELECT dbo.INVO_LST.CODE, SUM(dbo.INVO_LST.MEGHk) AS MEGH, SUM(dbo.INVO_LST.MABL_K) AS MABL, dbo.STUF_DEF.NAME AS KALA, dbo.TCOD_VAHEDS.NAMES AS VAHED, dbo.TCOD_STUFGROUP.NAMES AS GRP, dbo.mabstandard.price, SUM(dbo.INVO_LST.MEGHk * dbo.mabstandard.price) AS mabst, MASRAFST.MABLST, (MASRAFST.MABLST / dbo.mabstandard.price) AS MEGHST FROM dbo.INVO_LST INNER JOIN dbo.HEAD_LST ON dbo.INVO_LST.NUMBER = dbo.HEAD_LST.NUMBER AND dbo.INVO_LST.TAG = dbo.HEAD_LST.TAG INNER JOIN dbo.STUF_DEF ON dbo.INVO_LST.CODE = dbo.STUF_DEF.CODE INNER JOIN dbo.TCOD_VAHEDS ON dbo.STUF_DEF.VAHED = dbo.TCOD_VAHEDS.CODE INNER JOIN dbo.TCOD_STUFGROUP ON dbo.STUF_DEF.RADAH = dbo.TCOD_STUFGROUP.CODE INNER JOIN dbo.mabstandard ON dbo.STUF_DEF.CODE = dbo.mabstandard.CODE INNER JOIN dbo.MASRAFST(@FROMDATE, @TODATE, @KONTROL) AS MASRAFST ON dbo.STUF_DEF.CODE = MASRAFST.HES_T WHERE (dbo.HEAD_LST.TAG = 10 OR dbo.HEAD_LST.TAG = 11) AND (dbo.HEAD_LST.DATE_N >= @FROMDATE) AND (dbo.HEAD_LST.DATE_N <= @TODATE) AND (dbo.HEAD_LST.DEPATMAN = 20) and ((dbo.HEAD_LST.USER_NAME = 'Mr Rahimi')  or (dbo.HEAD_LST.USER_NAME = 'mehr')  or (dbo.HEAD_LST.USER_NAME = 'sam')  or (dbo.HEAD_LST.USER_NAME = 'Mrs.Shakibaey')  or (dbo.HEAD_LST.USER_NAME = 'Dr majid dehghani')  or (dbo.HEAD_LST.USER_NAME = 'dmd')  or (dbo.HEAD_LST.USER_NAME = 'Mr mehdi fattahi')  or (dbo.HEAD_LST.USER_NAME = 'Mrs mina sheikhzadeh')  or (dbo.HEAD_LST.USER_NAME = 'sa41')  or (dbo.HEAD_LST.USER_NAME = 'fate')  or (dbo.HEAD_LST.USER_NAME = 'Mrs malieh zare')  or (dbo.HEAD_LST.USER_NAME = 'atena')  or (dbo.HEAD_LST.USER_NAME = 'a0125')  or (dbo.HEAD_LST.USER_NAME = 'saberi')  or (dbo.HEAD_LST.USER_NAME = 'Hani dashti')  or (dbo.HEAD_LST.USER_NAME = 'Mr nikonahad')  or (dbo.HEAD_LST.USER_NAME = 'fatemeh Abotalebi') ) GROUP BY dbo.INVO_LST.CODE, dbo.STUF_DEF.NAME, dbo.TCOD_VAHEDS.NAMES, dbo.TCOD_STUFGROUP.NAMES, dbo.mabstandard.price, MASRAFST.MABLST ) SELECT CODE, MEGH, MABL, KALA, VAHED, GRP, price, mabst, (mabst - MABL) AS MOGNERKH, MABLST, MEGHST, (MEGHST - MEGH) AS MOGMAS, ((MEGHST - MEGH) * price) AS MOGRMAS FROM MASRAF_SUB_CTE; END 
